import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry for textured plane render mode
  const planeGeometry = new THREE.PlaneGeometry(2, 1.25);

  // Create material with texture if available
  let planeMaterial;
  if (config.imageUrl) {
    const texture = ctx.textureLoader.load(config.imageUrl);
    planeMaterial = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true
    });
  } else {
    planeMaterial = new THREE.MeshBasicMaterial({
      color: new THREE.Color(0xe8ecf2),
      transparent: true
    });
  }

  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text content via font atlas (MSDF)
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];

    const textMesh = ctx.fontAtlas.createTextMesh(textContent, {
      fontSize: 0.34,
      color: new THREE.Color(0x16161d),
      align: 'center'
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives if any
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach((primitive) => {
      ctx.primitives[primitive.name](group, primitive.params);
    });
  }

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x,
      config.scenePosition.y,
      config.scenePosition.z
    );

    if (config.scenePosition.rotationXYZ) {
      group.rotation.order = 'XYZ';
      group.rotation.set(
        config.scenePosition.rotationXYZ[0],
        config.scenePosition.rotationXYZ[1],
        config.scenePosition.rotationXYZ[2]
      );
    }

    if (config.scenePosition.scaleXYZ) {
      group.scale.set(
        config.scenePosition.scaleXYZ[0],
        config.scenePosition.scaleXYZ[1],
        config.scenePosition.scaleXYZ[2]
      );
    }
  }

  // Cleanup function
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();

    if (planeMaterial.map) {
      planeMaterial.map.dispose();
    }

    group.traverse((child) => {
      if (child.geometry && child !== planeMesh) {
        child.geometry.dispose();
      }
      if (child.material && child !== planeMesh) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });

    gsap.killTweensOf(group);
  };

  group.userData.handlers = {};

  return group;
}
